import {KEY,dateKey,addDay,monday,initialState,ensurePlan,FIXED_NG,migrateState,eat,lastEaten,favoriteIds,matches} from './model.js';
const app=document.querySelector('#app');let menus,fruits,state,selected=dateKey(),view='today',timer;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(timer);timer=setTimeout(()=>el.style.display='none',4000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('保存できませんでした。ブラウザの保存容量や設定をご確認ください。');}}
function label(d){return new Date(d+'T12:00:00').toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'long'});}
function nav(){return `<div class="date-nav"><button data-day="-1" aria-label="前の日">‹</button><div class="date-center"><strong>${label(selected)}</strong><button data-today>今日に戻る</button></div><button data-day="1" aria-label="次の日">›</button></div>`;}
function today(){const p=ensurePlan(state,selected,menus);if(p.status==='empty')return nav()+`<section class="empty"><h2>条件に合う献立がありません</h2><p>重複せずに選べる献立が足りません。NG食材の設定をご確認ください。</p><button data-view="settings">家族設定を見る</button></section>`;const m=menus.find(m=>m.id===p.menuId);const fruit=fruits[Math.abs(Math.round(new Date(selected+'T12:00:00').getTime()/86400000))%fruits.length];const ingredients=[...m.ingredients,{name:fruit.name,amount:fruit.amount}];const checked=state.checks[selected]||{};const warnings=state.family.flatMap(f=>f.ng.filter(t=>matches(m,t)).map(t=>`${esc(f.name)}のNG食材「${esc(t)}」が含まれています。`));const last=lastEaten(state,m.id),history=state.history[selected];return nav()+`<section class="hero"><div class="eyebrow">TONIGHT'S MENU</div><h1>${esc(m.name)}</h1><div class="badges"><span class="badge">◷ ${m.totalTime?"準備":"約"}${m.time}分${m.totalTime?`（炊飯込み約${m.totalTime}分）`:""}</span><span class="badge">${m.difficulty==='very_easy'?'超かんたん':'かんたん'}</span><span class="badge">3人前</span></div><div class="hero-note">${esc(m.note)}${last?`<br>最後に食べた日：${last}`:''}</div></section>${warnings.map(w=>`<div class="warning">⚠ ${w}</div>`).join('')}<div class="columns"><div><section class="panel"><div class="section-head"><h2>今日の買い物</h2><span class="muted">${ingredients.filter((_,i)=>checked[i]).length} / ${ingredients.length}</span></div><p class="muted">買ったらチェック。おうちにあれば、そのままで。</p>${ingredients.map((i,index)=>`<label class="check-row"><input type="checkbox" data-check="${index}" ${checked[index]?'checked':''}><span>${esc(i.name)}<small>${esc(i.amount)}${i.package?'・'+esc(i.package):''}</small></span></label>`).join('')}<div class="pantry"><strong>家にあればOK</strong>${m.seasonings.map(esc).join(' ／ ')}</div></section><section class="panel fruit"><span class="eyebrow">AFTER DINNER</span><h3>食後に、${esc(fruit.name)}</h3><p class="muted">${esc(fruit.prep)}</p></section></div><div><section class="panel"><div class="section-head"><h2>さっと、作ろう</h2><span class="muted">${m.steps.length}ステップ</span></div><ol class="steps">${m.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="muted">ご飯は炊飯器におまかせ。汁物はインスタントでも。</p></section><section class="panel"><h2>今日のごちそうさま</h2><p class="muted">食事の記録や評価で、週間献立が変わることはありません。</p>${history&&history.menuId!==m.id?`<p class="muted">この日の食事記録：${esc(menus.find(x=>x.id===history.menuId)?.name||'以前の献立')}。新しい予定とは別に保存しています。</p><button class="text-button" data-unrecord>この日の食事記録を取り消す</button>`:selected>dateKey()?'<p class="muted">食事の記録は当日からできます。</p>':`<button class="primary" data-eat>${history?'食事済み ✓':'食べたことを記録する'}</button><p class="muted">評価して記録する</p><div class="ratings"><button data-rating="like" class="${history?.rating==='like'?'selected':''}">♡ また作りたい</button><button data-rating="dislike" class="${history?.rating==='dislike'?'selected':''}">あまり好評でない</button></div>${history?'<button class="text-button" data-unrecord>この日の食事記録を取り消す</button>':''}`}</section></div></div>`;}
function week(){const start=monday(selected);return `<div class="eyebrow">WEEKLY MENU</div><h1 class="page-title">今週の食卓</h1><p class="top-note">月曜から日曜まで、毎日ちがう献立。記録は不要です。</p><div class="date-nav"><button data-weekshift="-7">‹ 前の週</button><strong>${start.slice(5).replace('-','/')} – ${addDay(start,6).slice(5).replace('-','/')}</strong><button data-weekshift="7">次の週 ›</button></div>${Array.from({length:7},(_,i)=>{const d=addDay(start,i),p=ensurePlan(state,d,menus),m=menus.find(m=>m.id===p.menuId);return `<button class="week-row ${d===dateKey()?'selected':''}" data-date="${d}"><span class="week-day">${'月火水木金土日'[i]}<small>${Number(d.slice(-2))}日</small></span><span class="week-copy"><strong>${esc(m?.name||'献立の候補なし')}</strong><small>${m?`${m.totalTime?`準備${m.time}分 / 炊飯込み約${m.totalTime}分`:`約${m.time}分`} · 3人前${state.history[d]?.menuId===m.id?' · 食事済み':''}`:'家族設定を確認してください'}</small></span><span>›</span></button>`;}).join('')}`;}
function favorites(){const ids=favoriteIds(state);return `<div class="eyebrow">FAMILY FAVORITES</div><h1 class="page-title">また食べたい、をここに。</h1><p class="top-note">「また作りたい」と記録した、わが家の定番。</p>${ids.length?menus.filter(m=>ids.includes(m.id)).map(m=>`<section class="panel"><h2>${esc(m.name)}</h2><p class="muted">${m.totalTime?`準備${m.time}分 / 炊飯込み約${m.totalTime}分`:`約${m.time}分`} · 最後に食べた日 ${lastEaten(state,m.id)}</p></section>`).join(''):'<div class="empty"><h2>お気に入りは、これから。</h2><p class="muted">食後に「♡ また作りたい」を押すと<br>ここに集まります。</p></div>'}<h2 style="margin-top:32px">最近食べた料理</h2>${Object.keys(state.history).sort().reverse().slice(0,10).map(d=>`<div class="history-row"><small class="muted">${d}</small><br>${esc(menus.find(m=>m.id===state.history[d].menuId)?.name)}</div>`).join('')||'<p class="muted">まだ食事の記録はありません。</p>'}`;}
function settings(){return `<div class="eyebrow">OUR FAMILY</div><h1 class="page-title">わが家の設定</h1><p class="top-note">3人の「好き」に、少しずつ近づけて。</p><section class="panel"><h2>献立から除外するもの</h2><p>${FIXED_NG.map(esc).join(" ／ ")}</p><p class="muted">在庫・食事記録・評価は献立の選択に使いません。</p></section><form id="family-form" class="settings">${state.family.map((f,i)=>`<section class="panel"><h2>${i+1}人目</h2><label>名前<input name="name-${i}" value="${esc(f.name)}" maxlength="24" required></label><label>NG食材 <small class="muted">献立候補から除外</small><input name="ng-${i}" value="${esc(f.ng.join('、'))}" placeholder="例：ピーマン、牡蠣" maxlength="300"></label><label>苦手な食材 <small class="muted">メモとして保存</small><input name="dislike-${i}" value="${esc(f.dislike.join('、'))}" placeholder="例：魚、きのこ、辛い" maxlength="300"></label></section>`).join('')}<p class="muted">食材は「、」またはカンマで区切って入力。保存すると、NG食材に合わせて週全体を見直します。苦手な食材のメモや食事記録では献立は変わりません。</p><button class="primary">家族設定を保存する</button></form><section class="panel" style="margin-top:24px"><h2>このアプリについて</h2><p class="muted">データはこのブラウザ内に保存されます。別の端末との共有はありません。Safariの共有メニューから「ホーム画面に追加」で、アプリのように使えます。</p></section>`;}
function render(){app.innerHTML=view==='today'?today():view==='week'?week():view==='favorites'?favorites():settings();document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));save();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state)return;try{if(b.dataset.view){view=b.dataset.view;if(view==='today')selected=dateKey();render();window.scrollTo(0,0);}if(b.dataset.day){selected=addDay(selected,Number(b.dataset.day));render();}if(b.hasAttribute('data-today')){selected=dateKey();render();}if(b.dataset.date){selected=b.dataset.date;view='today';render();window.scrollTo(0,0);}if(b.dataset.weekshift){selected=addDay(selected,Number(b.dataset.weekshift));render();}if(b.hasAttribute('data-week')){view='week';render();}if(b.hasAttribute('data-eat')||b.dataset.rating){eat(state,selected,b.dataset.rating||state.history[selected]?.rating||null);render();toast('ごちそうさまを記録しました');}if(b.hasAttribute('data-unrecord')){delete state.history[selected];render();toast('食事の記録を取り消しました');}}catch(err){toast(err.message);}});
app.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.checks[selected]??={};state.checks[selected][e.target.dataset.check]=e.target.checked;const pos=e.target.dataset.check;render();app.querySelector(`[data-check="${pos}"]`)?.focus({preventScroll:true});}});
app.addEventListener('submit',e=>{if(e.target.id!=='family-form')return;e.preventDefault();const fd=new FormData(e.target),tags=v=>String(v).split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean);state.family=state.family.map((f,i)=>({...f,name:fd.get('name-'+i).trim()||f.name,ng:tags(fd.get('ng-'+i)),dislike:tags(fd.get('dislike-'+i))}));render();toast('家族設定を保存しました');});
async function init(){try{[menus,fruits]=await Promise.all(['menus','fruits'].map(n=>fetch(`./data/${n}.json`).then(r=>{if(!r.ok)throw Error('load');return r.json();})));state=initialState();try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if(v.version!==1||!v.plans||!v.history||!Array.isArray(v.family)||v.family.length!==3||v.family.some(f=>!Array.isArray(f.ng)||!Array.isArray(f.dislike)))throw Error('invalid');if(v.plannerVersion!==2)localStorage.setItem(KEY+'-before-planner-v2',raw);state=migrateState({...state,...v,plannerVersion:v.plannerVersion});}}catch{toast('保存データを読み込めないため、初期状態で表示します。');}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'show_dinner_week',description:'選択中の日を含む週間献立を表示します。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('引数は不要です');view='week';render();return {weekStart:monday(selected)};}})).catch(()=>{});}}catch{app.innerHTML='<section class="empty"><h1>献立を読み込めませんでした</h1><p>通信状態を確認して、もう一度お試しください。</p><button onclick="location.reload()">再読み込み</button></section>';}}
init();
